resources.text:
.lab-panel {
  --lab-bg: #0f161a; --lab-bg2: #151f25; --lab-bg3: #1c2830; --lab-line: rgb(255 255 255 / 0.09); --lab-line2: rgb(255 255 255 / 0.16);
  --lab-text: #e3eaee; --lab-muted: #8b9ca4; --lab-accent: #2fc2ab; --lab-accent-ink: #03211c; --lab-warn: #ffc35a; --lab-bad: #ff6f61; --lab-good: #5fd68e;
  position: fixed; z-index: 80; display: flex; flex-direction: column; min-width: 360px; box-sizing: border-box;
  background: var(--lab-bg); color: var(--lab-text); border: 1px solid var(--lab-line2); border-radius: 12px;
  box-shadow: 0 18px 50px rgb(0 0 0 / 0.55), 0 0 0 1px rgb(0 0 0 / 0.4);
  font: 12px/1.4 Inter, ui-sans-serif, "Segoe UI", Roboto, sans-serif; color-scheme: dark; overflow: hidden;
}

.glass {
  background: linear-gradient(145deg, var(--ui-hi), transparent 42%), var(--ui-bg);
  border: 1px solid var(--ui-border);
  border-radius: 14px;
  box-shadow: var(--shadow);
}

.panel-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 10px;
  letter-spacing: 0.12em;
  color: var(--muted);
  margin-bottom: 10px;
}

.panel-title kbd {
  font: inherit;
  border: 1px solid var(--ui-border);
  border-radius: 5px;
  padding: 1px 5px;
}

.signal-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 8px 4px 6px;
  border-radius: 999px;
  border: 1px solid var(--ui-border);
  background: rgba(5, 16, 18, 0.55);
  font-size: 10.5px;
  color: var(--text);
}

.bw-icon-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 9px;
  border: 1px solid var(--bw-border);
  border-radius: var(--bw-radius);
  background: transparent;
  color: var(--bw-muted);
  white-space: nowrap;
}

.bw-icon-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 9px;
  border: 1px solid var(--bw-border);
  border-radius: var(--bw-radius);
  background: transparent;
  color: var(--bw-muted);
  font-size: 11px;
  white-space: nowrap;
}

.bw-inspector {
  position: absolute;
  top: 138px;
  right: 10px;
  width: 268px;
  max-height: calc(100dvh - 138px - 60px);
  overflow-y: auto;
  scrollbar-width: thin;
  pointer-events: auto;
  background: color-mix(in srgb, var(--bw-panel) 92%, transparent);
  border: 1px solid var(--bw-border);
  border-radius: var(--bw-radius);
}

.bw-inspector-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 6px 6px 6px 10px;
  border-bottom: 1px solid var(--bw-border);
}

.bw-field-input {
  width: 100%;
  height: 26px;
  padding: 0 6px;
  border: 1px solid var(--bw-border);
  border-radius: 5px;
  background: color-mix(in srgb, var(--bw-bg) 70%, transparent);
  color: var(--bw-text);
  font: inherit;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.bw-inspector-actions {
  display: flex;
  gap: 3px;
  padding: 6px 8px;
  border-bottom: 1px solid var(--bw-border);
}

.v2-icon > span, .v2-pill > span, .v2-seg-b > span, .v2-tabs.compact .v2-tab.icon:not(.on) > span, .v2-tabs.tight .v2-tab.icon > span, .v2-choice.icon > span,
.v2-verb > span, .v2-act > span {
  position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap;
}

.v2-pill, .v2-icon {
  position: relative; display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  width: 32px; height: 32px; padding: 0; flex: none;
  border: 1px solid var(--v-line); border-radius: 10px; background: var(--v-raise); color: var(--v-text);
}
